-- rule kernel: L:eliminate_cross_join (datafusion)
WITH cte1 AS (SELECT ARRAY['1'::text] AS c0, '2000-01-01 00:00:00+00'::timestamptz AS c1, a1.c0 AS c2 FROM tp AS a1, generate_series (10, 5) AS a2 (c0) WHERE (a2.c0 > a1.c0) GROUP BY ROLLUP (a1.c0)) SELECT '_'::text AS c0, 1000::bigint AS c1, 100::bigint AS c2 INTERSECT SELECT '[1,10)'::text AS c0, 0::bigint AS c1, (NULL::bigint + 10::bigint) AS c2 FROM cte1 AS a3 GROUP BY a3.c2;
